# The chain rule over a two-step composition
def f(x):
    return (x ** 2 + 1) * 3

def f_prime(x):
    return 3 * 2 * x

for x in [1.0, 2.0, 3.0]:
    h = 1e-6
    numeric = (f(x + h) - f(x - h)) / (2 * h)
    print(x, f_prime(x), round(numeric, 6))

# The two agree, so the chain rule was applied correctly
